@page { size: A4; margin: 12mm; }

body {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 12px;
  color: #000;
}

/* ===== HEADER ===== */
.header {
  display: grid;
  grid-template-columns: 1fr 260px;
  grid-template-areas:
    "company logo"
    "customer quote";
  gap: 10px;
}

.header-company { grid-area: company; }
.header-logo { grid-area: logo; text-align: right; }
.header-customer { grid-area: customer; }
.header-quote { grid-area: quote; }

.company-name { 
  font-size: 20px; 
  font-weight: 700; 
}

.small { 
  font-size: 11px; 
}

.quote-panel {
  border: 1px solid #000;
  width: 240px;
}

.quote-title {
  background: #d0d0d0;
  font-weight: 700;
  padding: 6px;
  border-bottom: 1px solid #000;
}

.b{
    font-size: 11px; 
    border-bottom: 1px solid black !important;
}

.quote-meta td {
  padding: 6px;
  border-bottom: 1px solid #000;
}

.rule { 
  border-top: 1.2px solid #000; 
  margin-top: 8px; 
}

.rule.thin { 
  border-top: 0.8px solid #000; 
}

/* ===== TABLES ===== */
.table-container {
  position: relative;
}

.tbl {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
}

.tbl th, .tbl td {
  border: 1px solid #000;
  padding: 6px;
  font-size: 10.5px;
}

.tbl thead th {
  background: #eaeaea;
  font-weight: 700;
}

.col-sr { 
  width: 6%; 
  text-align: center; 
}

.col-desc { 
  width: 40%; 
}

.col-cat { 
  width: 12%; 
  text-align: center; 
}

.col-hsn { 
  width: 10%; 
  text-align: center; 
}

.col-qty { 
  width: 8%; 
  text-align: center; 
}

.col-rate { 
  width: 12%; 
  text-align: right; 
}

.col-amt { 
  width: 12%; 
  text-align: right; 
}

/* ===== RIGHT TOTALS ===== */
.right-totals {
  width: 260px;
  margin-left: auto;
  margin-top: 8px;
  border-collapse: collapse;
  border: 1px solid #000;
}

.right-totals td {
  padding: 6px 10px;
  border-bottom: 1px solid #000;
  font-size: 11px;
}

.right-totals tr:last-child td {
  border-bottom: none;
}

.right-totals .lbl {
  text-align: right;
  font-weight: 600;
}

.right-totals .val {
  width: 90px;
  text-align: right;
  font-weight: 600;
}

.right-totals .grand td {
  font-weight: 700;
  font-size: 12px;
  background: #f0f0f0;
}

/* ===== MISC ===== */
.h6 { 
  font-weight: 700; 
  font-size: 13px; 
}

.mt-16 { 
  margin-top: 16px; 
}

.note {
  font-size: 10px;
  margin-top: 20px;
  text-align: center;
}

.terms-title {
  font-weight: bold; 
  margin-top: 12px;
}

