{# ======================== LETTERHEAD ========================= #}
<style>
@page {
    margin: 70px;
}

html, body {
    margin: 0;
    padding: 0 !important;
}

.print-format {
    width: 87%;
    margin: 0 auto !important;
    padding: 0 !important;
}
</style>




<div style="text-align:right; padding-top:10px; margin:-10px 0 0 0;">

  <div style="display:inline-block; text-align:left;">

    <!-- Company Logo -->
    <img src="/files/Bartakke logo.png" alt="Bartakke Letter Head" style="width:250px; margin-bottom:5px;">

    <!-- Company Info -->
    <div style="font-size:12px; line-height:1.8; color:#000;">

      <!-- Address -->
      <div style="display:flex; align-items:center; margin-bottom:3px; white-space:nowrap;">
        <img src="/files/locatiion-icon.png" style="width:12px !important; height:12px !important; margin-right:6px;">
        <span>L-20 Addl. MIDC, Satara - 415004, Maharashtra, India</span>
      </div>

      <!-- Phone -->
      <div style="display:flex; align-items:center; margin-bottom:3px;">
        <img src="/files/phone-icon.png" style="width:12px !important; height:12px !important; margin-right:6px;">
        <span>+91 2162 240431 / 284</span>
      </div>

      <!-- Email -->
      <div style="display:flex; align-items:center; margin-bottom:3px;">
        <img src="/files/email-icon.jpg" style="width:12px !important; height:12px !important; margin-right:6px;">
        <span>bepl@bartakke.co.in</span>
      </div>

      <!-- Website -->
      <div style="display:flex; align-items:center; margin-bottom:3px;">
        <img src="/files/web-icon.png" style="width:12px !important; height:12px !important; margin-right:6px;">
        <span>www.bartakkeenclousers.com</span>
      </div>

    </div>

  </div>

</div>








{# ======================== GST UNDER LOGO ===================== #}
<div class="header-gst">
    GST No.: {{ doc.company_gstin }}
</div>

<div class="proforma-page">

{# ======================== COMPANY ADDRESS ======================== #}
<table width="100%">
<tr>
<td width="55%">
    <div class="company-title">Bartakke Electrofab Pvt. Ltd.</div>
    <div class="company-address">
        L-20, Additional MIDC, Satara, Maharashtra, 415004<br>
        Tel.: 02162 24031/240284 &nbsp; Email: bepl@bartakke.co.in<br>
        Website : www.bartakkeenclousers.com<br>
        <b>State Code :</b> 27
    </div>
</td>

<td width="45%" align="right" valign="top">

<div class="title-box">

    <table class="proforma-inner-table" width="100%" cellspacing="0" cellpadding="0">

        <tr>
            <td colspan="4" class="p-header">
                Proforma Invoice
            </td>
        </tr>

        <tr>
            <td class="label-cell">
                Proforma No.
            </td>

            <td class="value-cell">
                {{ doc.name }}
            </td>

            <td class="label-cell">
                Date
            </td>

            <td class="value-cell">
                {{ frappe.utils.formatdate(doc.transaction_date, "dd-MM-yyyy") }}
            </td>
        </tr>

        <tr>
            <td class="label-cell">
                PO No.
            </td>

            <td class="value-cell">
                {{ doc.po_no or "" }}
            </td>

            <td class="label-cell">
                PO Date
            </td>

            <td class="value-cell">
                {{ frappe.utils.formatdate(doc.po_date, "dd-MM-yyyy") if doc.po_date else "" }}
            </td>
        </tr>

    </table>

</div>

</td>
</tr>
</table>

<br>

{# ======================== TO & CONSIGNEE ======================== #}
{% set cust_addr = frappe.get_doc("Address", doc.customer_address) if doc.customer_address else None %}
{% set ship_addr = frappe.get_doc("Address", doc.shipping_address_name) if doc.shipping_address_name else cust_addr %}

<table width="100%">
<tr>
<td width="50%">
    <div class="section-title">To</div>
    <div class="address-block">
        <b>{{ doc.customer_name }}</b><br>

        {% set addr = (doc.address_display or "")
            | replace("<br>", ", ")
            | replace("\n", ", ")
            | replace(" ,", ",")
            | replace(", ,", ",")
        %}

        <div style="line-height:1.35; text-align:left;">
            {{ addr.split(",")[0] }}, {{ addr.split(",")[1] }}<br>

            {{ addr.split(",")[2] }}, {{ addr.split(",")[3] }}, 
            {{ addr.split(",")[4] }}<br>

            {{ addr.split(",")[5] }}, {{ addr.split(",")[6] }}
        </div>
        GST No: {{ cust_addr.gstin if cust_addr else "" }}<br>
        State Code: {{ cust_addr.gst_state_number if cust_addr else "" }}
    </div>
</td>

<td width="50%">
    <div class="section-title">Consignee Details</div>
    <div class="address-block">
        <b>{{ doc.customer_name }}</b><br>

        {% set saddr = (doc.address_display or "")
            | replace("<br>", ", ")
            | replace("\n", ", ")
            | replace(" ,", ",")
            | replace(", ,", ",")
        %}

        <div style="line-height:1.35; text-align:left;">
            {{ saddr.split(",")[0] }}, {{ saddr.split(",")[1] }}<br>

            {{ saddr.split(",")[2] }}, {{ saddr.split(",")[3] }},
            {{ saddr.split(",")[4] }}<br>

            {{ saddr.split(",")[5] }}, {{ saddr.split(",")[6] }}
        </div>
        GST No: {{ ship_addr.gstin if ship_addr else "" }}<br>
        State Code: {{ ship_addr.gst_state_number if ship_addr else "" }}
    </div>
</td>
</tr>
</table>

<br>

{# ======================== GST NAMESPACE ======================== #}
{% set ns = namespace(basic_total=0, cgst=0, sgst=0, igst=0) %}

{# ======================== ITEMS TABLE ========================= #}
<table width="100%" class="main-table">
<thead>
<tr>
<th>S.No</th>
<th>Description of Goods</th>
<th>HSN</th>
<th>Qty</th>
<th>Unit</th>
<th>Rate</th>
<th>Amount</th>
<th>GST</th>
<th>Total</th>
</tr>
</thead>

<tbody>
{% for i in doc.items %}
{% set amount = (i.qty or 0) * (i.rate or 0) %}
{% set cgst_amt = amount * (i.cgst_rate or 0) / 100 %}
{% set sgst_amt = amount * (i.sgst_rate or 0) / 100 %}
{% set igst_amt = amount * (i.igst_rate or 0) / 100 %}
{% set gst_amt = cgst_amt + sgst_amt + igst_amt %}
{% set total = amount + gst_amt %}

{% set ns.basic_total = ns.basic_total + amount %}
{% set ns.cgst = ns.cgst + cgst_amt %}
{% set ns.sgst = ns.sgst + sgst_amt %}
{% set ns.igst = ns.igst + igst_amt %}

<tr>
<td align="center">{{ loop.index }}</td>
<td>{{ i.item_name }}</td>
<td align="center">{{ i.gst_hsn_code }}</td>
<td align="center">{{ i.qty }}</td>
<td align="center">{{ i.uom }}</td>
<td align="right">{{ i.rate }}</td>
<td align="right">{{ amount | round(2) }}</td>
<td align="right">{{ gst_amt | round(2) }}</td>
<td align="right">{{ total | round(2) }}</td>
</tr>
{% endfor %}
</tbody>
</table>

<br>

{# ======================== AMOUNT IN WORDS ======================== #}
<table class="amount-words">
<tr>
<td><b>Amount Chargeable (in words)</b></td>
<td>
{% if doc.advance_paid and doc.advance_paid > 0 %}
    {{ frappe.utils.money_in_words(doc.grand_total - doc.advance_paid) }}
{% else %}
    {{ frappe.utils.money_in_words(doc.grand_total) }}
{% endif %}
</td>
</tr>
</table>

<br>

{# ======================== BANK + GST SUMMARY ======================== #}
<table width="100%">
<tr valign="top">

<td width="50%" class="bank-details">
<b>Our Bank Details</b><br>
Bank Name: STATE BANK OF INDIA<br>
Account No: 10390181756<br>
IFSC: SBIN0004174<br>
Swift Code: SBININBB925
</td>

<td width="50%" align="right">
<table width="65%" align="right" class="summary-table">
<tr>
<td><b>Basic Total</b></td>
<td align="right">{{ ns.basic_total | round(2) }}</td>
</tr>

{% for tax in doc.taxes %}
    {% if "TRANSPORT" in tax.description | upper %}
    <tr>
        <td><b>{{ tax.description }}</b></td>
        <td align="right">{{ tax.tax_amount | round(2) }}</td>
    </tr>
    {% endif %}
{% endfor %}

{% if ns.igst > 0 %}
<tr>
    <td><b>IGST @{{ ns.igst_rate or ((ns.igst / ns.basic_total * 100) | round) }}%</b></td>
    <td align="right">{{ ns.igst | round(2) }}</td>
</tr>
{% else %}
<tr>
    <td><b>CGST @{{ ns.cgst_rate or ((ns.cgst / ns.basic_total * 100) | round) }}%</b></td>
    <td align="right">{{ ns.cgst | round(2) }}</td>
</tr>
<tr>
    <td><b>SGST @{{ ns.sgst_rate or ((ns.sgst / ns.basic_total * 100) | round) }}%</b></td>
    <td align="right">{{ ns.sgst | round(2) }}</td>
</tr>
{% endif %}

<tr>
<td><b>Total</b></td>
<td align="right"><b>{{ doc.grand_total | round(2) }}</b></td>
</tr>

{% if doc.advance_paid and doc.advance_paid > 0 %}
<tr>
<td><b>Advance Paid</b></td>
<td align="right">{{ doc.advance_paid | round(2) }}</td>
</tr>
<tr>
<td><b>Outstanding Amount</b></td>
<td align="right"><b>{{ (doc.grand_total - doc.advance_paid) | round(2) }}</b></td>
</tr>
{% endif %}
</table>
</td>

</tr>
</table> 

<br><br>

{# ======================== SIGNATURE ======================== #}
<table width="100%" class="sign-table">
<tr>
<td><b>{{ frappe.get_doc('User', doc.owner).full_name if doc.owner else "" }}</b></td>
<td></td>
<td align="right"><b>For Bartakke Electrofab Pvt. Ltd.</b></td>
</tr>
<tr>
<td class="sig-label">Prepared By</td>
<td class="sig-label" align="center">Checked By</td>
<td class="sig-label" align="right">Authorised Signatory</td>
</tr>
</table>

</div>

