/* ===== MAIN CONTAINER ===== */
.delivery-challan.print-format {
    font-family: Helvetica, Arial, sans-serif;
    color: #000;
    font-size: 12px;
    padding:10%;
}

/* ===== PAGE WIDTH CONTROL ===== */
#container {
    width: 100%;
}

/* ===== LEFT BLOCK: Deliver To ===== */
.delivery-challan .col-60 {
    width: 60%;
    float: left;
    position: absolute;
    margin-left: 15px;
    padding-right: 8px;
}

/* ===== RIGHT BLOCK: Challan / PO Info ===== */
.delivery-challan .col-40 {
    width: 40%;
    float: right;
    padding-left: 8px;
}

/* ===== CLEAR FLOAT ===== */
.delivery-challan .clear-both {
    clear: both;
}

/* ===== TITLE ===== */
.delivery-challan .title {
    text-align: center;
    font-weight: bold;
    font-size: 12px;
    margin: 10px 0;
}

/* ===== DELIVER TO LABEL ===== */
.delivery-challan .deliver-to-label {
    font-weight: bold;
}

/* ===== CAPTION LINE ===== */
.caption-line {
    font-weight: bold;
    margin-top: 15px;
}

/* ===== TABLE BASE ===== */
.delivery-challan table {
    width: 100%;
    border-collapse: collapse;
}

/* ===== TABLE CELL ===== */
.delivery-challan td,
.delivery-challan th {
    padding: 4px 6px;
    vertical-align: top;
}

/* ===== ALIGNMENTS ===== */
.delivery-challan .text-center { text-align: center; }
.delivery-challan .text-right  { text-align: right; }
.delivery-challan .bold        { font-weight: bold; }
.delivery-challan .small-text  { font-size: 11px;  }

/* ===== BORDERS ===== */
.delivery-challan .bordered td,
.delivery-challan .bordered th {
    border: 1px solid #000;
}

/* ===== ITEMS TABLE ===== */
.items-table {
    margin-top: 10px;
}

/* ===== FOOTER ===== */
.footer-table {
    width: 100%;
    margin-top: 40px;
}

.footer-table td {
    padding: 4px 6px;
    border: 0;
}

/* LEFT FOOTER */
.footer-left {
    text-align: left;
    font-size: 11px;
}

/* RIGHT FOOTER */
.footer-right {
    text-align: right;
    font-size: 11px;
}

.signatory {
    margin-top: 40px;
    display: inline-block;
}

/* ===== SECTION SPACING ===== */
.delivery-challan .section {
    margin-top: 20px;
}

.box {
    position: relative;
    left: 27px;
}

