html:
{%- set company_doc = frappe.get_doc("Company", doc.company) -%}

<style>
@page {
  size: A4;
  margin: 20mm;
}

/* ── RESET ───────────────────────────────────────────────── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ── WRAPPER ─────────────────────────────────────────────── */
.jw {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 9pt;
  color: #000;
  width: 100%;
  border: 1.5px solid #000;
}

/* ── SHARED UTILS ────────────────────────────────────────── */
table       { border-collapse: collapse; width: 100%; }
.b          { font-weight: bold; }
.tc         { text-align: center; }
.vt         { vertical-align: top; }
.bb         { border-bottom: 1px solid #000; }
.bt         { border-top:    1px solid #000; }
.br         { border-right:  1px solid #000; }

/* ══════════════════════════════════════════════════════════
   SEC 1 — LOGO | TITLE
   ══════════════════════════════════════════════════════════ */
.s1-logo {
  width: 52%;
  padding: 8px 10px 8px 10px;
  border-right: 1px solid #000;
  vertical-align: middle;
}

.s1-logo img {
  max-height: 54px;
  max-width: 210px;
  display: block;
}

.s1-logo .co-text {
  font-size: 16pt;
  font-weight: 900;
}

.s1-right {
  width: 48%;
  vertical-align: middle;
  text-align: center;
}

.title-wrap {
  padding: 0 20px;
  text-align: center;
}

.title-box {
  display: inline-block;
  border: 1.5px solid #000;
  padding: 6px 30px;
  font-size: 11pt;
  font-weight: bold;
  text-align: center;
  white-space: nowrap;
}

.orig-line {
  text-align: right;
  font-size: 8pt;
  padding: 5px 20px 0 0;
  color: #000;
}

/* ══════════════════════════════════════════════════════════
   SEC 2 — COMPANY DETAIL | CHALLAN META
   ══════════════════════════════════════════════════════════ */
.s2-left {
  width: 60%;
  padding: 6px 10px;
  border-right: 1px solid #000;
  vertical-align: top;
}

.co-name {
  font-size: 11.5pt;
  font-weight: bold;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: #000;
}

.co-addr {
  font-size: 8.5pt;
  line-height: 1.5;
  text-align: center;
  margin-top: 3px;
  color: #000 !important;
}

.co-addr a,
.co-addr span,
.co-addr p,
.co-addr div {
  color: #000 !important;
  text-decoration: none !important;
  display: inline;
}

.co-addr br + br {
  display: none;
}

.s2-right {
  width: 40%;
  padding: 0 !important;
  vertical-align: top;
  border-left: 0;
}

.s2-right .meta-grid {
  margin: -1px 0 -1px -1px;
}

.meta-grid {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
  table-layout: fixed;
  height: 100%;
}

.meta-grid td {
  padding: 10px 12px;
  font-size: 10pt;
  vertical-align: middle;
  border: 1px solid #000;
}

.meta-grid tr:first-child td {
  border-top: none;
}

.meta-grid tr:last-child td {
  border-bottom: none;
}

.meta-grid td:first-child {
  border-left: none;
}

.meta-grid td:last-child {
  border-right: none;
}

.meta-lbl {
  font-weight: bold;
  white-space: nowrap;
  width: 48%;
}

.meta-val {
  font-weight: bold;
  width: 52%;
}

/* ══════════════════════════════════════════════════════════
   SEC 3 — 3-COLUMN ADDRESS
   ══════════════════════════════════════════════════════════ */
.addr-hdr td {
  border: 1px solid #000;
  padding: 4px 7px;
  font-weight: bold;
  width: 33.33%;
  font-size: 8.5pt;
}

.addr-main td {
  border: 1px solid #000;
  padding: 5px 7px;
  vertical-align: top;
  width: 33.33%;
  font-size: 8.5pt;
  line-height: 1.5;
}

.addr-sub td {
  border: 1px solid #000;
  padding: 3px 7px;
  width: 33.33%;
  font-size: 8.5pt;
}

/* ══════════════════════════════════════════════════════════
   SEC 4 — DETAIL OF SUPPLY
   ══════════════════════════════════════════════════════════ */
.dos td {
  padding: 3px 8px;
  font-size: 8.5pt;
}

/* ══════════════════════════════════════════════════════════
   SEC 5 — NATURE OF PROCESSING
   ══════════════════════════════════════════════════════════ */
.nop td {
  padding: 4px 8px;
  font-size: 8.5pt;
}

/* ══════════════════════════════════════════════════════════
   SEC 6 — ITEMS TABLE
   ══════════════════════════════════════════════════════════ */
.itbl {
  table-layout: fixed;
}

.itbl th,
.itbl td {
  border: 1px solid #000;
  padding: 4px 3px;
  text-align: center;
  vertical-align: middle;
  font-size: 8pt;
  word-break: break-word;
  overflow-wrap: break-word;
}

.itbl th {
  font-weight: bold;
}

/* col widths — must sum 100% */
.ic-sr   { width:  5%; }
.ic-hsn  { width: 10%; }
.ic-desc { width: 24%; text-align: left !important; padding-left: 5px !important; }
.ic-size { width: 13%; }
.ic-nos  { width:  9%; }
.ic-wt   { width:  9%; }
.ic-sq   { width:  9%; }
.ic-col  { width: 22%; }

.itbl tfoot td {
  font-weight: bold;
}

/* ══════════════════════════════════════════════════════════
   SEC 7 — SIGNATURE
   ══════════════════════════════════════════════════════════ */
.sig-l {
  width: 50%;
  padding: 6px 10px 30px;
  vertical-align: top;
  border-right: 1px solid #000;
}

.sig-r {
  width: 50%;
  padding: 6px 10px 30px;
  vertical-align: top;
  text-align: right;
}

.sig-line {
  margin-top: 36px;
  font-size: 8pt;
}

/* ══════════════════════════════════════════════════════════
   SEC 8 — RECEIPT TABLE
   ══════════════════════════════════════════════════════════ */
.rcpt-hdr td {
  text-align: center;
  font-weight: bold;
  padding: 5px 8px;
  border-bottom: 1px solid #000;
  font-size: 9pt;
}

.rtbl {
  table-layout: fixed;
}

.rtbl th {
  border: 1px solid #000;
  padding: 5px 4px;
  font-weight: bold;
  text-align: center;
  font-size: 8.5pt;
  word-break: break-word;
  line-height: 1.4;
}

.rtbl td {
  border: 1px solid #000;
  padding: 14px 4px;
  text-align: center;
  font-size: 8.5pt;
}

.rc1 { width: 20%; }
.rc2 { width: 20%; }
.rc3 { width: 22%; }
.rc4 { width: 18%; }
.rc5 { width: 20%; }

@media print {
  .jw   { border: 1.5px solid #000 !important; }
  .itbl { page-break-inside: avoid; }
}
</style>

<div class="jw">

