          </tr>
          <tr>
            <td class="meta-lbl">Date Of Issue</td>
            <td class="meta-val">
              {{ frappe.format(doc.transaction_date, {"fieldtype":"Date"}) }}
            </td>
          </tr>
          {%- if doc.schedule_date %}
          <tr>
            <td class="meta-lbl">Required By</td>
            <td class="meta-val">
              {{ frappe.format(doc.schedule_date, {"fieldtype":"Date"}) }}
            </td>
          </tr>
