        <div class="b">{{ doc.company }}</div>
        {%- if doc.shipping_address_display -%}
          <div>{{ doc.shipping_address_display | safe }}</div>
        {%- elif doc.billing_address_display -%}
          <div>{{ doc.billing_address_display | safe }}</div>
        {%- endif -%}
      </td>
    </tr>
    <tr class="addr-sub">
      <td>State:-&nbsp;&nbsp;Maharashtra</td>
      <td>State:-&nbsp;&nbsp;Maharashtra</td>
      <td>State:-&nbsp;&nbsp;Maharashtra</td>
    </tr>
    <tr class="addr-sub">
      <td>Sate Code:-&nbsp;&nbsp;27</td>
      <td>Sate Code:-&nbsp;&nbsp;27</td>
      <td>Sate Code:-&nbsp;&nbsp;27</td>
    </tr>
