      <td>GSTIN No.&nbsp;&nbsp;<b>{{ doc.company_gstin or '—' }}</b></td>
      <td>GSTIN No.&nbsp;&nbsp;<b>{{ doc.company_gstin or '—' }}</b></td>
    </tr>
  </table>

  <table class="bt bb dos">
    <tr>
      <td colspan="4" class="b" style="padding:3px 8px;">Detail Of Supply.</td>
    </tr>
  </table>

  <table class="bb dos" style="table-layout:fixed;">
    <colgroup>
      <col style="width:18%;">
      <col style="width:42%;">
      <col style="width:20%;">
      <col style="width:20%;">
    </colgroup>
