            {%- if a > 0 and b > 0 -%}
              {{ "%.2f"|format(a) }}mm <br> *{{ "%.2f"|format(b) }}mm
            {%- elif a > 0 -%}
              {{ "%.2f"|format(a) }}mm
            {%- endif -%}
